def is_nested(string):
    open_count = 0
    has_nested = False
    for ch in string:
        if ch == '[':
            open_count += 1
        elif ch == ']':
            if open_count > 0:
                if open_count >= 2:
                    has_nested = True
                open_count -= 1
            else:
                open_count = 0
    return has_nested
